presets.css:
/* =========================================
   Puff · 线下常用模板 - 香脆薄巧（甜点星空版）
   配色灵感：#8E97A3 / #D5ECF2 / #FADAE2 / #FFFAE8
   ========================================= */

:root {
  --sweet-slate: #8E97A3; /* 薄巧薄雾灰蓝（字色/描边） */
  --sweet-blue: #D5ECF2;  /* 薄荷冰蓝（我方卡片） */
  --sweet-pink: #FADAE2;  /* 莓果糖霜粉（对方卡片/重点） */
  --sweet-cream: #FFFAE8; /* 奶油黄底色 */
  --sweet-text: #535A65;  /* 柔和黑巧字色，保障阅读清晰度 */
}

/* —— 入口列表 —— */
.off-app {
  --off-list-bg: var(--sweet-cream);
  --off-list-border: rgba(142, 151, 163, 0.18);
  --off-list-radius: 22px;
  --off-list-ava-size: 54px;
}
html[data-theme="dark"] .off-app {
  --off-list-bg: #272A30;
  --off-list-border: rgba(213, 236, 242, 0.1);
}

/* 筛选分类标签 */
.off-inbox-filter button {
  color: var(--sweet-slate);
  background: transparent;
  border-radius: 999px;
  transition: all 0.25s ease;
}
.off-inbox-filter button.on {
  color: var(--sweet-text);
  background: var(--sweet-pink);
  font-weight: 600;
  box-shadow: 0 2px 10px rgba(250, 218, 226, 0.45);
}
html[data-theme="dark"] .off-inbox-filter button.on {
  background: rgba(250, 218, 226, 0.22);
  color: #fff;
}

/* 列表容器 */
.off-list {
  background: var(--off-list-bg);
  border: 1px solid var(--off-list-border);
  border-radius: var(--off-list-radius);
  overflow: hidden;
  box-shadow: 0 6px 20px rgba(142, 151, 163, 0.08);
}
.off-list-btn {
  padding: 16px 16px;
}
.off-list-ava {
  border-radius: 18px; /* 头像微圆角更具甜点感 */
  border: 2px solid #fff;
  box-shadow: 0 3px 8px rgba(142, 151, 163, 0.15);
}
.off-list-body strong {
  font-size: 1.25rem;
  color: var(--sweet-text);
}
.off-list-body span {
  opacity: 0.85;
  color: var(--sweet-slate);
}
.off-list-go.is-new {
  font-size: 18px;
  color: var(--sweet-slate);
}

/* —— 当面共处 —— */
.off-app.off-app-session {
  --off-card-user: var(--sweet-blue);   /* 我方日记卡片：冰爽薄荷蓝 */
  --off-card-peer: var(--sweet-pink);   /* 对方日记卡片：甜心草莓粉 */
  --off-card-border: rgba(142, 151, 163, 0.14);
  --off-card-shadow: 0 8px 24px rgba(142, 151, 163, 0.09);
  --off-prose-font: "Quicksand", "PingFang SC", "Noto Serif SC", sans-serif;
  --off-dock-bg: rgba(255, 250, 232, 0.94); /* 底栏软奶油黄 */
  color: var(--sweet-text);
}
html[data-theme="dark"] .off-app.off-app-session {
  --off-card-user: #2C353D;
  --off-card-peer: #3A2F34;
  --off-card-border: rgba(213, 236, 242, 0.08);
  --off-card-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  --off-dock-bg: rgba(36, 38, 43, 0.95);
}

/* 无壁纸时的当面舞台默认底色（奶油泡芙色） */
.off-app.off-app-session:not(:has(.off-stage.has-bg)) .off-stage {
  background: var(--sweet-cream);
}
html[data-theme="dark"] .off-app.off-app-session:not(:has(.off-stage.has-bg)) .off-stage {
  background: #1C1E22;
}

/* 当面顶栏（带有小星点修饰） */
.off-app.off-app-session .off-stage-head {
  border-bottom: 1px solid rgba(142, 151, 163, 0.12);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}
html[data-theme="dark"] .off-app.off-app-session .off-stage-head {
  border-bottom-color: rgba(213, 236, 242, 0.08);
}
.off-app.off-app-session .off-stage-scene {
  font-weight: 600;
  letter-spacing: 0.05em;
  color: var(--sweet-text);
}
.off-app.off-app-session .off-stage-scene::before {
  content: "✧ ";
  color: var(--sweet-slate);
  font-size: 12px;
}
.off-app.off-app-session .off-stage-scene::after {
  content: " ✧";
  color: var(--sweet-slate);
  font-size: 12px;
}

/* 日记卡片：圆角加大并点缀右上角微闪小星星 */
.off-app.off-app-session .off-passage-sheet {
  background: var(--off-card-peer);
  border: 1px solid var(--off-card-border);
  box-shadow: var(--off-card-shadow);
  border-radius: 20px;
  position: relative;
}
.off-app.off-app-session .off-passage-sheet::after {
  content: "✦";
  position: absolute;
  top: 10px;
  right: 14px;
  font-size: 12px;
  color: var(--sweet-slate);
  opacity: 0.35;
  pointer-events: none;
}
.off-app.off-app-session .off-passage.is-me .off-passage-sheet {
  background: var(--off-card-user);
}
.off-app.off-app-session .off-passage.is-me .off-passage-sheet::after {
  content: "✧";
}

/* 推演标签：闪光小星徽章 */
.off-app .off-thinking-chip {
  background: rgba(255, 255, 255, 0.7);
  color: var(--sweet-slate);
  border: 1px solid rgba(142, 151, 163, 0.2);
  border-radius: 999px;
  padding: 2px 10px;
  font-size: 11px;
  letter-spacing: 0.04em;
}
.off-app .off-thinking-chip::before {
  content: "★ ";
  font-size: 9px;
  color: #f7bbcf;
}
html[data-theme="dark"] .off-app .off-thinking-chip {
  background: rgba(250, 218, 226, 0.12);
  color: var(--sweet-pink);
  border-color: rgba(250, 218, 226, 0.2);
}

/* —— 正文排版：所有段落首行缩进 2 个字 —— */
.off-app.off-app-session .off-prose-para,
.off-app.off-app-session .off-prose-narr,
.off-app.off-app-session .off-prose-plain,
.off-app.off-app-session .off-prose-dial {
  font-family: var(--off-prose-font);
  line-height: 1.85;
  font-size: 14.5px;
  color: var(--sweet-text);
  text-indent: 2em; /* 核心：首行缩进两空格/两字符 */
}

/* 对话略微加深字重，更加生动 */
.off-app.off-app-session .off-prose-dial {
  font-style: normal;
  font-weight: 500;
}
.off-app.off-app-session .off-passage.is-me .off-prose-dial {
  font-weight: 400;
}

/* 底栏输入区 */
.off-app.off-app-session .off-stage-dock {
  background: var(--off-dock-bg);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-top: 1px solid rgba(142, 151, 163, 0.12);
}
.off-compose-bar {
  background: #ffffff;
  border: 1px solid rgba(142, 151, 163, 0.2);
  border-radius: 999px;
  box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.02);
}
html[data-theme="dark"] .off-compose-bar {
  background: #2B2F36;
  border-color: rgba(213, 236, 242, 0.12);
}
.off-compose-send {
  background: var(--sweet-pink);
  color: var(--sweet-text);
  border-radius: 50%;
  box-shadow: 0 2px 8px rgba(250, 218, 226, 0.6);
  transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.off-compose-send:active {
  transform: scale(0.9);
}
html[data-theme="dark"] .off-compose-send {
  background: var(--sweet-blue);
  color: #1A1D20;
}
